<!doctype html>
<html lang="<?= \App\Core\Localization::current() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= \App\Core\t("Active session") ?>s — c0m.me</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><?php require __DIR__ . '/partials/language-switcher.php'; ?><main class="shell"><nav class="nav"><a class="brand" href="/dashboard">c0m.me</a><a class="nav-link" href="/dashboard"><?= \App\Core\t("Dashboard") ?></a></nav><section class="hero compact"><span class="eyebrow"><?= \App\Core\t("ACCOUNT SECURITY") ?></span><h1><?= \App\Core\t("Active devices") ?></h1><p><?= \App\Core\t("Review devices signed in to your account. Device and browser details are informational and are not used as authentication proof.") ?></p><form method="post" action="/sessions/revoke-others"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token(), ENT_QUOTES, 'UTF-8') ?>"><button class="button" type="submit"><?= \App\Core\t("Sign out other devices") ?></button></form></section><section class="feature-grid" style="grid-template-columns:1fr"><?php foreach ($sessions as $item): ?><article><b><?= $item['is_current'] ? \App\Core\t('THIS DEVICE') : \App\Core\t('ACTIVE SESSION') ?></b><h2><?= htmlspecialchars($item['user_agent'] ?: 'Unknown browser', ENT_QUOTES, 'UTF-8') ?></h2><p>IP: <?= htmlspecialchars($item['ip_display'], ENT_QUOTES, 'UTF-8') ?><br>Last activity: <?= htmlspecialchars($item['last_activity'], ENT_QUOTES, 'UTF-8') ?><br>Expires: <?= htmlspecialchars($item['expires_at'], ENT_QUOTES, 'UTF-8') ?></p><?php if (!$item['is_current']): ?><form method="post" action="/sessions/revoke"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="session_id" value="<?= htmlspecialchars($item['id'], ENT_QUOTES, 'UTF-8') ?>"><button class="nav-link" type="submit"><?= \App\Core\t("Revoke session") ?></button></form><?php endif; ?></article><?php endforeach; ?><?php if (!$sessions): ?><article><p><?= \App\Core\t("No active sessions found.") ?></p></article><?php endif; ?></section></main></body></html>
